        var validMixedPayload = (Page1WeeklyFactsPayload)ValidPayload(SupplementalSectionKind.Page1WeeklyFacts, scheduleEvidence.Id, 2026, 1); validMixedPayload.WinImplications.ForEach(x => x.EvidenceId = page1EditorialEvidence.Id); validMixedPayload.Storyline.EvidenceId = page1EditorialEvidence.Id; validMixedPayload.StatOfWeekSelection!.EditorialEvidenceId = page1EditorialEvidence.Id;
