        True(typeof(WeeklyResolvedLayoutBuilder).GetMethods().Single(x => x.Name == nameof(WeeklyResolvedLayoutBuilder.Build)).GetParameters().Select(x => x.ParameterType).SequenceEqual([typeof(WeeklyGameNotesComposition)]), "WP 7.1 production API consumes only WeeklyGameNotesComposition");
        True(layout.Fonts.Count == 2 && layout.Fonts.Select(x => x.Family).Order().SequenceEqual(["Arial Narrow", "Impact"]) && layout.Fonts.All(x => x.FileSha256.Length == 64 && x.MetricIdentity.Length == 64 && x.FaceIndex == 0), "Physical font preflight records exact binary and metric identities without fallback");
        True(layout.Fonts.All(x => x.Weight != "Bold"), "Arial Narrow Bold is not required by the resolved visible grammar");
        var missingTypes = composition.Design.Typography.Select(x => x.Family == "Impact" ? x with { Family = "Minden Missing Font" } : x).ToList(); var missingFont = WeeklyResolvedLayoutBuilder.Build(composition with { Design = composition.Design with { Typography = missingTypes } }); True(!missingFont.IsRenderReady && missingFont.Pages.Count == 10 && missingFont.Diagnostics.Count == 10 && missingFont.Diagnostics.All(x => x.Code == ResolvedLayoutDiagnosticCode.RequiredFontUnavailable) && missingFont.SemanticIdentity.Length == 64, "Missing physical font preserves ten blocked pages deterministically without fallback or substitution");
        PublicationDesignContract ChangeType(TypographyRole role, Func<TypographyRange, TypographyRange> change) => composition.Design with { Typography = composition.Design.Typography.Select(x => x.Role == role ? change(x) : x).ToList() };
        var unusedMissing = WeeklyResolvedLayoutBuilder.Build(composition with { Design = ChangeType(TypographyRole.PageTitle, x => x with { Family = "Minden Unused Missing Font" }) }); True(unusedMissing.IsRenderReady && unusedMissing.Fonts.All(x => x.Family != "Minden Unused Missing Font"), "An unavailable unused regular face is excluded from usage-derived preflight");
        var usedMissingRegular = WeeklyResolvedLayoutBuilder.Build(composition with { Design = ChangeType(TypographyRole.Feature, x => x with { Family = "Minden Used Missing Regular" }) }); True(StableFontFailure(usedMissingRegular), "A used missing regular face blocks through the stable ten-page preflight path");
        var usedMissingBold = WeeklyResolvedLayoutBuilder.Build(composition with { Design = ChangeType(TypographyRole.Data, x => x with { Family = "Minden Used Missing Bold", Bold = true }) }); True(StableFontFailure(usedMissingBold), "A used missing bold face cannot bypass preflight or escape later through face lookup");
        var incompatibleBold = WeeklyResolvedLayoutBuilder.Build(composition with { Design = ChangeType(TypographyRole.Data, x => x with { Bold = true }) }); True(StableFontFailure(incompatibleBold), "A requested bold face that resolves only to regular is rejected through stable preflight without synthetic bold");
        True(layout.IsRenderReady && layout.Fonts.All(x => x.FileSha256.Length == 64), "Every used available physical face succeeds after usage-derived preflight");
        True(layout.SemanticIdentity == rebuilt.SemanticIdentity && layout.SemanticIdentity.Length == 64 && layout.Pages.SelectMany(x => x.Primitives).Select(x => x.Key).Distinct(StringComparer.Ordinal).Count() == layout.Pages.Sum(x => x.Primitives.Count), "Equivalent resolved layouts have deterministic semantic identity and globally unique primitive keys");
        True(layout.Pages.All(x => x.PageBounds == new CompositionRect(0, 0, 612, 792)), "Every resolved page uses the governed physical page");
