        var shells = layout.Pages.Select(p => p.Primitives.Where(x => x.Key.Contains(".Shell.", StringComparison.Ordinal)).Select(x => (x.Kind, Relative(x.Bounds, p.PageBounds))).ToList()).ToList(); True(shells.Skip(1).All(x => x.Select(y => (y.Kind, y.Item2)).SequenceEqual(shells[0].Select(y => (y.Kind, y.Item2)))), "All ten pages share one deterministic shell geometry and layer grammar");
        True(layout.Pages.All(p => p.Primitives.SequenceEqual(p.Primitives.OrderBy(x => x.Layer).ThenBy(x => x.Sequence))), "Primitive layer and sequence establish deterministic renderer draw order");
